# Generated by packaging/chocolatey/package.sh in @REPO@; changes here are overwritten.
#
# Removes what chocolateyInstall.ps1 installed: the files in C:\Program Files\WatermelonPGP
# and its Path entry. It refuses while a Windows service runs that watermelon.exe, and never
# touches data directories or master keys.
$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'common.ps1')

$services = @(Get-WatermelonService)
if ($services) {
  $names = ($services | ForEach-Object { $_.Name }) -join ', '
  throw @"
The Windows service $names runs $exe; removing it would leave a service that can't start.
Remove the service first (its data directory and master key stay), then uninstall again:
  watermelon service uninstall$(if ($names -ne 'watermelon') { ' --name <name>' })
  choco uninstall watermelon-pgp
"@
}

foreach ($item in 'watermelon.exe', 'README.md', 'CHANGELOG.md', 'LICENSE-MIT', 'LICENSE-APACHE', 'docs', 'contrib') {
  $path = Join-Path $installDir $item
  if (Test-Path $path) { Remove-Item $path -Recurse -Force }
}
# Anything else there was put there by someone else: leave it, and the folder with it.
if ((Test-Path $installDir) -and -not (Get-ChildItem $installDir -Force)) { Remove-Item $installDir -Force }

$machinePath = [Environment]::GetEnvironmentVariable('Path', 'Machine')
$kept = @($machinePath -split ';' | Where-Object { $_ -and ($_.TrimEnd('\') -ine $installDir) })
if ($kept.Count -ne @($machinePath -split ';' | Where-Object { $_ }).Count) {
  [Environment]::SetEnvironmentVariable('Path', ($kept -join ';'), 'Machine')
}

Write-Host "watermelon-pgp is uninstalled. Data directories (such as C:\ProgramData\WatermelonPGP) and master keys are left as they are; delete them yourself once you no longer need them."
